<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {fetchCatalogListing,fetchCatalog} from '../services/catalog'
import type {CatalogListing} from '../services/catalog-types'
import {catalogPhoto,catalogTitle,metroCaption} from '../services/catalog-photos'
import {useMemberStore} from '../stores/member'
import {usePilotStore} from '../stores/pilot'
import {money} from '../data/mock'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import AppSheet from '../components/AppSheet.vue'
import {contactApi} from '../services/contact'
import CatalogCard from '../components/CatalogCard.vue'
import ListingLocationMap from '../components/ListingLocationMap.vue'
const route=useRoute(),router=useRouter(),member=useMemberStore(),pilot=usePilotStore()
const home=ref<CatalogListing>(),related=ref<CatalogListing[]>([]),busy=ref(false),error=ref(''),historyError=ref(''),contactOpen=ref(false),contactBusy=ref(false),contactMessage=ref(''),imageOpen=ref(false),costOpen=ref(false)
let controller:AbortController|undefined,request=0
const paymentMonths=computed(()=>home.value?.paymentMethod==='押一付一'?1:home.value?.paymentMethod==='押一付三'||home.value?.paymentMethod==='押二付三'?3:null)
const firstFunds=computed(()=>home.value&&paymentMonths.value!==null?home.value.rent*paymentMonths.value+home.value.deposit:null)
const mapUrl=computed(()=>home.value&&home.value.locationStatus!=='UNVERIFIED'&&typeof home.value.longitude==='number'&&Number.isFinite(home.value.longitude)&&Math.abs(home.value.longitude)<=180&&typeof home.value.latitude==='number'&&Number.isFinite(home.value.latitude)&&Math.abs(home.value.latitude)<=90?`https://uri.amap.com/marker?position=${home.value.longitude},${home.value.latitude}&name=${encodeURIComponent(home.value.community)}&coordinate=gaode&callnative=1`:null)
const facilityLabels:Record<string,string>={privateBathroom:'独立卫生间',privateKitchen:'独立厨房',gas:'燃气',balcony:'阳台',airConditioning:'空调',refrigerator:'冰箱',washingMachine:'洗衣机',waterHeater:'热水器',elevator:'电梯',furnished:'家具',petsAllowed:'允许宠物',cookingAllowed:'可做饭'}
function facilityValue(key:string){const state=home.value?.amenities[key];if(state==='UNKNOWN'||!state)return '未知';return ['petsAllowed','cookingAllowed'].includes(key)?state==='YES'?'允许':'不允许':state==='YES'?'有':'无'}
async function record(){if(!home.value||!member.loggedIn)return;historyError.value='';try{await member.recordHistory(home.value.id)}catch{historyError.value='浏览记录暂未保存，可点此重试'}}
async function load(){const id=++request;controller?.abort();controller=new AbortController();busy.value=true;error.value='';home.value=undefined;related.value=[];contactOpen.value=false;contactBusy.value=false;imageOpen.value=false;costOpen.value=false;try{const result=await fetchCatalogListing(String(route.params.id),controller.signal);if(id!==request)return;home.value=result;busy.value=false;await member.restore();if(id!==request)return;void record();const more=await fetchCatalog({district:result.district,rentalType:result.rentalType},0,controller.signal);if(id===request)related.value=more.items.filter(h=>h.id!==result.id).slice(0,2)}catch(cause){if(id===request&&!home.value)error.value=cause instanceof Error?cause.message:'加载失败，请重试'}finally{if(id===request)busy.value=false}}
function needLogin(){if(member.loggedIn)return false;void router.push({path:'/account',query:{redirect:route.fullPath}});return true}
async function favorite(){if(!home.value||needLogin())return;try{await member.toggleFavorite(home.value.id)}catch(cause){pilot.notify(cause instanceof Error?cause.message:'收藏失败，请重试')}}
async function contact(){
  if(!home.value||needLogin()||contactBusy.value)return
  const token=member.token,id=home.value.id,version=request
  const current=()=>token===member.token&&id===home.value?.id&&version===request
  contactBusy.value=true
  try{
    const owner=await member.privateCall(t=>contactApi.owner(t,id))
    if(!current())return
    if(!owner.claimed){contactMessage.value='该模拟房源还没有演示发布方。可用另一个账号在联系页面认领，再回来发起对话。';contactOpen.value=true;return}
    if(owner.isMine){contactMessage.value='这是你认领的模拟房源。其他账号发来的消息会出现在联系页面。';contactOpen.value=true;return}
    const conversation=await member.privateCall(t=>contactApi.start(t,id))
    if(current())await router.push(`/messages/${conversation.id}`)
  }catch(cause){if(current())pilot.notify(cause instanceof Error?cause.message:'联系暂不可用，请重试')}
  finally{if(current())contactBusy.value=false}
}
watch(()=>member.token,()=>{contactOpen.value=false;contactBusy.value=false;contactMessage.value=''})
function fallback(event:Event){const image=event.target as HTMLImageElement;if(!image.src.endsWith('/placeholder.svg'))image.src='/assets/catalog/placeholder.svg'}
watch(()=>route.params.id,()=>void load(),{immediate:true})
onBeforeUnmount(()=>{++request;controller?.abort()})
</script>
<template><AppHeader title="房源详情" back hide-avatar><button v-if="home" class="icon-button" :aria-label="member.favoriteIds.includes(home.id)?'取消收藏房源':'收藏房源'" :aria-pressed="member.favoriteIds.includes(home.id)" :disabled="member.loggedIn&&(!member.favoritesReady||member.busyIds.has(home.id))" @click="favorite"><AppIcon name="heart" :fill="member.favoriteIds.includes(home.id)?'currentColor':'none'"/></button></AppHeader><main v-if="busy" class="page rental-loading" role="status">正在加载房源…</main><main v-else-if="error||!home" class="page rental-state"><AppIcon name="home" :size="32"/><h1>房源暂时加载不了</h1><p>{{ error }}</p><button class="secondary" @click="load">重新加载</button><RouterLink to="/listings" class="text-action">返回房源列表</RouterLink></main><main v-else class="page real-detail"><button class="real-detail-hero" aria-label="放大室内示意图" @click="imageOpen=true"><img :src="catalogPhoto(home)" alt="室内示意照片，非该房源实拍" @error="fallback"/><span>室内示意 · 非该房源实拍</span><i><AppIcon name="image" :size="16"/></i></button><section class="real-summary"><div class="between"><p class="real-price">{{ money(home.rent) }}<small>/月</small></p><button class="text-action muted" @click="costOpen=true">费用说明<AppIcon name="chevron-right" :size="15"/></button></div><h1>{{ catalogTitle(home) }}</h1><p class="small muted">{{ home.district }} · {{ home.town }} · 模拟房源</p><div class="real-specs"><div><strong>{{ home.area }}<small>㎡</small></strong><span>建筑面积</span></div><div><strong>{{ home.rentalType==='SHARED'?'合租单间':`${home.bedrooms} 居室` }}</strong><span>出租方式</span></div><div><strong>{{ home.orientation }}</strong><span>{{ home.floor }}</span></div></div><p class="small muted">整套户型：{{ home.layout }}<br/>装修：{{ home.decoration }} · 入住：{{ home.availability }}（源数据）</p><button v-if="historyError" class="text-action muted" @click="record">{{ historyError }}</button></section><section class="real-section"><div class="between"><h2>位置与日常出行</h2><a v-if="mapUrl" :href="mapUrl" target="_blank" rel="noopener noreferrer" class="text-action" aria-label="高德查看位置">高德查看<AppIcon name="arrow-right" :size="15"/></a></div><p class="small muted">{{ home.address==='待核验'?'详细位置待核验':home.address }}</p><ListingLocationMap :longitude="home.longitude" :latitude="home.latitude" :location-status="home.locationStatus" :community="home.community"/><div class="real-location"><AppIcon name="map-pin" :size="20"/><div><strong>{{ metroCaption(home) }}</strong><span>{{ home.metroLines.length?home.metroLines.join(' / '):'地铁线路待补充' }}</span></div></div><p class="tiny muted">位置为小区级参考；地铁步行时间不是到工作地的通勤时间。</p></section><section class="real-section"><h2>房间设施</h2><div class="real-amenities"><div v-for="(label,key) in facilityLabels" :key="key"><span>{{ label }}</span><strong :class="{muted:home.amenities[key]==='UNKNOWN'}">{{ facilityValue(key) }}</strong></div></div></section><section class="real-section"><h2>租住费用</h2><dl class="rental-ledger"><div><dt>月租金</dt><dd>{{ money(home.rent) }}/月</dd></div><div><dt>押金</dt><dd>{{ money(home.deposit) }}</dd></div><div><dt>付款方式</dt><dd>{{ home.paymentMethod }}</dd></div><div><dt>物业费（周期未注明）</dt><dd>{{ home.propertyFee===null?'待补充':money(home.propertyFee) }}</dd></div><div v-if="firstFunds!==null" class="ledger-total"><dt>首期租金 + 押金</dt><dd>{{ money(firstFunds) }}</dd></div></dl><p class="tiny muted">费用基于模拟数据；首期资金未计入物业、水电等额外项目，实际需核验合同。</p></section><section class="real-section"><details class="rental-details"><summary>房源完整描述<AppIcon name="chevron-down" :size="17"/></summary><p class="small muted">{{ home.description }}</p></details><details class="rental-details"><summary>看房时重点检查<AppIcon name="chevron-down" :size="17"/></summary><p class="small muted">确认出租人身份、房屋权属与合同条款；现场检查采光、隔音、水电、设施和维修责任，拍照记录交付状态。</p></details><details class="rental-details"><summary>数据与照片来源<AppIcon name="chevron-down" :size="17"/></summary><p class="small muted">{{ home.dataNature }}，价格、面积、设施和入住状态均为模拟，不代表实际在租。照片来自Pexels，仅供室内示意，与该小区和房屋没有对应关系。</p></details><p class="real-source-id">{{ home.id }}</p></section><section v-if="related.length" class="real-section"><div class="between"><h2>同区域再看看</h2><RouterLink :to="{path:'/listings',query:{district:home.district}}" class="text-action muted">全部<AppIcon name="chevron-right" :size="15"/></RouterLink></div><CatalogCard v-for="other in related" :key="other.id" :home="other"/></section></main><div v-if="home&&!busy&&!error" class="real-detail-actions"><div><strong>{{ money(home.rent) }}</strong><small>/月</small></div><button class="primary" :disabled="contactBusy" @click="contact">{{ contactBusy?'正在打开…':'联系房东' }}<AppIcon name="message" :size="17"/></button></div><AppSheet v-model="contactOpen" title="联系房东"><p class="small muted">{{ contactMessage }}</p><template #footer><RouterLink class="primary" :to="{path:'/messages',query:{claim:home?.id}}" @click="contactOpen=false">前往联系<AppIcon name="arrow-right" :size="17"/></RouterLink></template></AppSheet><AppSheet v-model="imageOpen" title="室内示意图" description="非该房源实拍"><img v-if="home" :src="catalogPhoto(home)" class="real-full-image" alt="室内示意，非该房源实拍"/></AppSheet><AppSheet v-model="costOpen" title="费用说明"><dl v-if="home" class="rental-ledger"><div><dt>首期租金 · {{ paymentMonths===null?'周期待核验':`${paymentMonths}个月` }}</dt><dd>{{ paymentMonths===null?'待补充':money(home.rent*paymentMonths) }}</dd></div><div><dt>押金</dt><dd>{{ money(home.deposit) }}</dd></div><div v-if="firstFunds!==null" class="ledger-total"><dt>首期需准备</dt><dd>{{ money(firstFunds) }}</dd></div></dl><p class="small muted">按原数据“{{ home?.paymentMethod }}”计算，不含物业费、水电或其他未知费用。</p></AppSheet></template>
<style scoped>.real-detail{padding-top:8px;padding-bottom:calc(110px + var(--safe-bottom))}.real-detail-hero{position:relative;width:100%;height:250px;border-radius:20px;overflow:hidden;padding:0;background:var(--surface)}.real-detail-hero img{width:100%;height:100%;object-fit:cover}.real-detail-hero>span{position:absolute;bottom:12px;left:12px;font-size:11px;background:#fff;padding:5px 8px;border-radius:5px}.real-detail-hero>i{position:absolute;right:12px;bottom:12px;display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#fff}.real-summary{padding:24px 0 28px}.real-price{font-size:31px;font-weight:600;letter-spacing:-.04em;line-height:1.4}.real-price small{font-size:12px;font-weight:400;letter-spacing:0;color:var(--muted);margin-left:5px}.real-summary h1{font-size:23px;line-height:1.6;margin:12px 0 10px}.real-specs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:26px 0}.real-specs>div{display:flex;flex-direction:column;gap:9px}.real-specs>div+div{border-left:1px solid var(--line);padding-left:14px}.real-specs strong{font-size:18px;font-weight:500;overflow-wrap:anywhere}.real-specs small,.real-specs span{font-size:12px;color:var(--muted);font-weight:400}.real-specs strong small{margin-left:3px}.real-section{border-top:1px solid var(--line);padding:24px 0}.real-section h2{font-size:18px;font-weight:600}.real-section>.small{margin:12px 0;line-height:1.85}.real-location{display:flex;gap:14px;align-items:center;background:var(--surface);padding:18px;border-radius:15px;margin:16px 0}.real-location strong{font-size:14px;font-weight:500;display:block}.real-location span{display:block;font-size:12px;color:var(--muted);margin-top:8px}.real-amenities{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px 12px;padding:24px 0 4px}.real-amenities>div{display:flex;flex-direction:column;gap:8px;font-size:12px}.real-amenities strong{font-weight:500;font-size:13px}.real-source-id{color:var(--muted);font-size:12px;margin-top:18px}.real-detail-actions{position:fixed;bottom:0;left:50%;transform:translateX(-50%);z-index:50;width:min(100%,640px);padding:14px var(--gutter) calc(14px + var(--safe-bottom));display:flex;align-items:center;gap:18px;background:#fff;border-top:1px solid var(--line)}.real-detail-actions>div{flex:1;min-width:0}.real-detail-actions strong{font-size:23px;font-weight:600;letter-spacing:-.03em}.real-detail-actions small{font-size:12px;color:var(--muted);margin-left:4px}.real-detail-actions .primary{flex:1.1;white-space:nowrap}.real-full-image{width:100%;height:auto;max-height:65dvh;object-fit:contain;border-radius:14px}@media(max-width:359px){.real-detail-hero{height:210px}.real-summary h1{font-size:21px}.real-specs{gap:8px}.real-specs>div+div{padding-left:10px}.real-specs strong{font-size:16px}.real-detail-actions strong{font-size:20px}}
</style>
